    },
    {
      "document_id": "DEV-001-D02",
      "published_on": "2026-02-06",
      "text": "Effective 2026-02-01, total active spending authority for DEV-001 River Clinic becomes 115 million crowns. This is a total ceiling, not an increment or a cash payment."
    },
    {
      "document_id": "DEV-001-D03",
      "published_on": "2026-02-20",
      "text": "A contract for DEV-001 River Clinic worth 35 million crowns was signed on 2026-02-19, but it remains entirely unpaid. This does not change the already stated budget authority."
    },
    {
      "document_id": "DEV-001-D04",
      "published_on": "2026-03-17",
      "text": "Proposed cash payment of 25 million crowns for DEV-001 River Clinic scheduled for 2026-04-04 remains unsettled. It should not be described as money already paid."
    },
    {
      "document_id": "DEV-001-D05",
      "published_on": "2026-05-12",
      "text": "Proposed cash payment of 185 million crowns for DEV-001 River Clinic scheduled for 2026-07-11 remains unsettled. It should not be described as money already paid."
    },
    {
      "document_id": "DEV-001-D06",
      "published_on": "2026-06-21",
      "text": "A contract for DEV-001 River Clinic worth 10 million crowns was signed on 2026-06-20, but it remains entirely unpaid. This does not change the already stated budget authority."
    },
    {
      "document_id": "DEV-001-D07",
      "published_on": "2026-09-18",
      "text": "A cash payment for DEV-001 River Clinic of 30 million crowns is proposed for 2026-10-07 but has not settled. Do not describe it as money already paid."
    },
    {
      "document_id": "DEV-001-D08",
      "published_on": "2026-09-19",
      "text": "A settled external cash transfer of 55 million crowns for DEV-001 River Water with payment reference DEV-001-W1 and settlement date 2026-09-18. Reporting may occur later."
    }
  ]
}

